import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { SheetBody } from '../../slots/defs/sheetBody';
import { claimsKey } from '../claims/useClaims';
import { peopleKey } from '../people/usePeople';

/** A paste box: lines of name,amount,date,note (the note may hold commas; a blank date is the sheet's
 *  today; a note ending in " #<reference>" gives the claim that external reference) each add a draft claim, in order, for the person on the sheet with that name. The server checks
 *  every line first: one refused line refuses the paste and adds nothing. Shows how many were added
 *  (gone while it runs). */
function PasteClaims({ sheetId }: { sheetId: string }) {
  const [text, setText] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSingleFlight();
  const paste = useMutation({
    mutationFn: (t: string) => postJson<{ added: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/paste`, { text: t }),
    // The count shows as soon as the paste is done; the new rows follow once re-read (not awaited, so the
    // rows never show ahead of the count).
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });
  return (
    <form
      data-testid="paste"
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          paste.reset();
          return paste.mutateAsync(text);
        });
      }}
    >
      <label>
        Paste claims (name,amount,date,note per line){' '}
        <textarea
          data-testid="paste-claims"
          rows={4}
          value={text}
          onChange={(e) => {
            setText(e.target.value);
            paste.reset();
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="paste-submit" disabled={paste.isPending}>
        Add draft claims
      </button>
      {paste.isSuccess && (
        <>
          {' '}
          Added <strong data-testid="paste-added">{paste.data.added}</strong>
        </>
      )}
      {paste.isError && <p data-testid="paste-error">{paste.error.message}</p>}
    </form>
  );
}

export const contribution = SheetBody.fill({
  order: 14,
  Component: ({ sheetId }) => <PasteClaims sheetId={sheetId} />,
});
package net.officefloor.hq.app.paste;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Add a draft claim per pasted line, in order, for the person on the sheet with that name (ignoring case).
 *  One change: every line is checked first by the claim form's rules, so a refused line adds nothing and
 *  writes no audit record; otherwise each claim is added and written as CLAIM_ADDED. */
public class PasteClaims {
    private record Checked(Person person, PasteLine line, LocalDate date) {
    }

    public void paste(@PathVariable("sheetId") String sheetId, @Val PasteInput input,
            ServerHttpConnection connection, PersonRepository people, ClaimRepository claims, SheetRepository sheets,
            PeriodRepository periods, Audit audit, Rollup rollup, Out<PasteResult> result) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!people.sheetExists(id)) {
            throw new BadRequestException("no such sheet");
        }
        LocalDate entry = sheets.entryDate(id);
        List<Checked> checked = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        int n = 0;
        for (PasteLine line : input.lines()) {
            n++;
            try {
                Person person = people.findByName(id, line.name());
                if (person == null) {
                    throw new BadRequestException("no one on the sheet is named " + line.name());
                }
                LocalDate date = line.claim().date() != null ? line.claim().date() : entry;
                PeriodGuard.open(periods, id, claims.dueBy(id, person.id(), date));
                people.claimAllowed(id, person.id(), date);
                line.claim().checkCorrection(claims, id, person.id());
                line.claim().checkRef(claims, id, null);
                if (line.claim().ref() != null && !refs.add(line.claim().ref().toLowerCase(Locale.ROOT))) {
                    throw new BadRequestException("reference " + line.claim().ref() + " is given twice in the paste");
                }
                checked.add(new Checked(person, line, date));
            } catch (BadRequestException e) {
                throw new BadRequestException("line " + n + ": " + e.getMessage());
            }
        }
        for (Checked c : checked) {
            Rollup.Snapshot before = rollup.take(id);
